// OverLayUpload is the resolver for the overLayUpload field.
func (r *mutationResolver) OverLayUpload(ctx context.Context, files []*model.UploadFile) ([]*model.File, error) {
	// var images []image.Image

	// Configure Redis
	rdb := redis.ConfigureRedis()

	for i, file := range files {
		// Use the ReadSeeker interface
		f := file.File.File

		// Convert image to byte slice
		byteSlice, err := redis.ImageToByteSlice(f)
		if err != nil {
			return nil, fmt.Errorf(" Error converting image to byte slice: %v", err)
		}

		// Store byte slice in Redis
		key := fmt.Sprintf("image_key_%d", i)
		err = redis.PassByteSliceToRedis(rdb, key, byteSlice)
		if err != nil {
			return nil, fmt.Errorf(" Error storing byte slice in Redis: %v", err)
		}
	}

	// Retrieve images from Redis and save locally
	outputDir := "./uploaded_images"
	if _, err := os.Stat(outputDir); !os.IsNotExist(err) {
		if err := os.RemoveAll(outputDir); err != nil {
			return nil, fmt.Errorf("could not remove existing output directory: %v", err)
		}
	}
	if err := os.MkdirAll(outputDir, os.ModePerm); err != nil {
		return nil, fmt.Errorf("could not create output directory: %v", err)
	}

	for i := range files {
		key := fmt.Sprintf("image_key_%d", i)
		retrievedByteSlice, err := redis.RetrieveByteSliceFromRedis(rdb, key)
		if err != nil {
			return nil, fmt.Errorf(" Error retrieving byte slice from Redis: %v", err)
		}

		outputImage, err := redis.ByteSliceToImage(retrievedByteSlice)
		if err != nil {
			return nil, fmt.Errorf(" Error converting byte slice to image: %v", err)
		}

		// images = append(images, outputImage)

		// Save the image locally
		outputPath := filepath.Join(outputDir, fmt.Sprintf("image_%d.png", i))
		file, err := os.Create(outputPath)
		if err != nil {
			return nil, fmt.Errorf("could not create image file: %v", err)
		}
		defer file.Close()

		err = png.Encode(file, outputImage)
		if err != nil {
			return nil, fmt.Errorf("could not encode image to PNG: %v", err)
		}
	}

	// FFmpeg command to create video from images
	outputVideoPath := "./output/slideshow.mp4"
	ffmpegCmd := exec.Command("ffmpeg",
		"-framerate", "1/5", // 1 image every 5 seconds
		"-pattern_type", "glob", // Use glob pattern for input file
		"-i", filepath.Join(outputDir, "*.png"), // Input images
		"-vf", "scale=972:768", // Scale the video
		"-c:v", "libx264", // Video codec
		"-pix_fmt", "yuv420p", // Pixel format
		outputVideoPath) // Output file path

	output, err := ffmpegCmd.CombinedOutput()
	if err != nil {
		return nil, fmt.Errorf("ffmpeg error: %v, output: %s", err, output)
	}

	return []*model.File{{Name: "slideshow.mp4", Content: outputVideoPath}}, nil
}

